package com.example.data.questions

import com.example.data.model.AnswerType
import com.example.data.model.AppLanguage
import com.example.data.model.Question

/**
 * Balance catalog Part 1 providing high-difficulty questions for underrepresented categories:
 * - Everyday Knowledge: 30 Very Hard, 15 Challenge
 * - Language & Linguistics: 30 Very Hard, 15 Challenge
 * - Food & Culture: 30 Very Hard, 15 Challenge
 * All concepts are verified, authentic domain knowledge across English, Arabic, Spanish, and French.
 */
object HighDifficultyBalancePart1 {

  fun getQuestions(language: AppLanguage): List<Question> {
    val list = mutableListOf<Question>()
    buildEverydayQuestions(list, language)
    buildLanguageQuestions(list, language)
    buildFoodQuestions(list, language)
    return list
  }

