  private fun addBatch(list: MutableList<Question>, items: List<BalItem>, lang: AppLanguage) {
    for (item in items) {
      val qText = when (lang) {
        AppLanguage.ARABIC -> item.arabicQ
        else -> item.englishQ
      }
      val answers = when (lang) {
        AppLanguage.ARABIC -> item.answers
        else -> item.answers.filterNot { ans -> ans.any { it in '\u0600'..'\u06FF' } }
      }
      val tier = if (item.score >= 95) 6 else 5
      val prefix = if (tier == 6) "bal_c_" else "bal_vh_"
      list.add(
        Question(
          id = "${prefix}${item.concept}_${lang.code}",
          language = lang.code,
          category = item.category,
          difficulty = tier,
          question = qText,
          answerType = item.type,
          acceptedAnswers = if (answers.isNotEmpty()) answers else item.answers,
          correctNumericValue = item.numericVal,
          tolerance = if (item.numericVal != null) 0.01 else null,
          explanation = "Verified domain knowledge in ${item.category}.",
          difficultyScore = item.score,
          conceptId = item.concept
        )
      )
    }
  }

  data class BalItem(
    val concept: String,
    val englishQ: String,
    val arabicQ: String,
    val answers: List<String>,
    val score: Int,
    val category: String,
    val type: AnswerType = AnswerType.TEXT,
    val numericVal: Double? = null
  )
}
